import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import Axios from 'axios';
import './course.css';

function CourseSearch() {
  const navigate = useNavigate();
  const [data, setData] = useState([]);
  const [selectedCourse, setSelectedCourse] = useState('');
  const [courses, setCourses] = useState([]);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState('');

  const fetchAllData = async () => {
    setLoading(true);
    setMessage('');
    try {
      const response = await Axios.get('http://localhost:3002/details');
      const users = response.data.users || [];
      setData(users);
      // Extract unique course names
      const uniqueCourses = [...new Set(users.map((user) => user.course))].sort();
      setCourses(uniqueCourses);
      setLoading(false);
    } catch (error) {
      setLoading(false);
      setMessage('Error fetching data. Please try again.');
      console.error('Error fetching all data:', error);
    }
  };

  const fetchCourseData = async (course) => {
    if (!course) return;
    setLoading(true);
    setMessage('');
    try {
      const response = await Axios.post('http://localhost:3002/course', { course });
      const users = response.data.users || [];
      setData(users);
      setLoading(false);
      if (users.length === 0) {
        setMessage('No records found for this course.');
      }
    } catch (error) {
      setLoading(false);
      setMessage('Error searching course. Please try again.');
      console.error('Error searching course:', error);
    }
  };

  // Handle course selection
  const handleCourseChange = (event) => {
    const course = event.target.value;
    setSelectedCourse(course);
    if (course === '') {
      fetchAllData(); // Reset to all data if no course is selected
    } else {
      fetchCourseData(course);
    }
  };

  // Initial data fetch
  useEffect(() => {
    fetchAllData();
  }, []);

  return (
    <div className="app-container">
     
      <div className="content-container">
        <div className="course-search-card">
          <h2 className="title">Course Search</h2>
          <div className="form-group">
            <label htmlFor="course">Select Course</label>
            <select
              id="course"
              value={selectedCourse}
              onChange={handleCourseChange}
              disabled={loading}
              className="course-select"
            >
              <option value="">All Courses</option>
              {courses.map((course, index) => (
                <option key={index} value={course}>
                  {course}
                </option>
              ))}
            </select>
          </div>

          {message && (
            <div className={`message ${message.includes('Error') ? 'error' : 'info'}`}>
              {message}
            </div>
          )}

          {loading ? (
            <div className="loading">Loading...</div>
          ) : (
            <div className="table-container">
              <table className="data-table">
                <thead>
                  <tr>
                    <th>District</th>
                    <th>Stream & Subjects</th>
                    <th>Course</th>
                    <th>Z-Range</th>
                  </tr>
                </thead>
                <tbody>
                  {data.map((row) => (
                    <tr key={row._id}>
                      <td>{row.district}</td>
                      <td>
                        <div>{row.stream}</div>
                        <div>Subject 1: {row.subject1}</div>
                        <div>Subject 2: {row.subject2}</div>
                        <div>Subject 3: {row.subject3}</div>
                      </td>
                      <td>{row.course}</td>
                      <td>
                        {row.zValue1} - {row.zValue2}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

export default CourseSearch;
